import{_ as t,o as e,c as r,a2 as d}from"./chunks/framework.doxMM-x8.js";const f=JSON.parse('{"title":"Lab Word 项目文档","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/docs/","contentType":"overview","prev":false,"next":{"text":"快速开始","link":"/getting-started/quickstart"}},"headers":[],"relativePath":"docs/index.md","filePath":"docs/index.md"}'),o={name:"docs/index.md"};function n(i,a,c,h,l,s){return e(),r("div",null,[...a[0]||(a[0]=[d('<h1 id="lab-word-项目文档" tabindex="-1">Lab Word 项目文档 <a class="header-anchor" href="#lab-word-项目文档" aria-label="Permalink to &quot;Lab Word 项目文档&quot;">​</a></h1><p>Lab Word 面向实验室数字孪生。当前先建立设备模型的 Three.js 呈现层，再讨论设备摆放与真实状态关联。</p><h2 id="选择你的任务" tabindex="-1">选择你的任务 <a class="header-anchor" href="#选择你的任务" aria-label="Permalink to &quot;选择你的任务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任务</th><th>从哪里开始</th><th>可观察结果</th></tr></thead><tbody><tr><td>启动现有应用</td><td><a href="./../getting-started/quickstart">快速开始</a></td><td>API 就绪、Web 注册页可访问</td></tr><tr><td>查看设备模型</td><td><a href="./../guides/lab-viewer">Lab Viewer 预览</a></td><td>在独立预览中看到设备并导入本地 GLB</td></tr><tr><td>修改项目</td><td><a href="./../architecture/project-structure">项目结构</a></td><td>找到应用组装与业务所有权</td></tr><tr><td>查阅接口</td><td><a href="./../reference/api">API</a>与<a href="./../reference/config">配置</a></td><td>定位当前生成合同与默认值</td></tr></tbody></table><h2 id="当前能力与计划" tabindex="-1">当前能力与计划 <a class="header-anchor" href="#当前能力与计划" aria-label="Permalink to &quot;当前能力与计划&quot;">​</a></h2><p>应用已有身份、成员、知识库、文件与任务等<a href="./../guides/platform">平台能力</a>。Lab Viewer v1 已能独立运行，预览画面已接受；正式 Lab 路由、登录后入口和生产懒加载的集成验收仍待完成。</p><p>本轮的本地 GLB 导入在浏览器会话内处理，不上传到服务器；设备数据接入、控制与场景摆放后置。<a href="./../architecture/lab-word">产品范围</a>说明这一边界；<a href="https://github.com/CaiZongyuan/labworld/blob/a4354a6936c10c0426b959ffa8f3debbc5afa68a/docs/plans/lab-viewer-m0.md" target="_blank" rel="noreferrer">呈现层计划</a>记录后续验收。</p><h2 id="阅读与维护" tabindex="-1">阅读与维护 <a class="header-anchor" href="#阅读与维护" aria-label="Permalink to &quot;阅读与维护&quot;">​</a></h2><p>教程逐步增加同一份 Lab 业务代码；独立指南以任务、前提、源码、命令、结果和失败边界组织。当前内容只声明仓库实际存在的能力，预览与计划分别标明状态。</p><p>中英文页面按章节配对，API 与配置从实现生成。修改功能时同步更新相关文档和<a href="./../testing/feedback-loop">验证入口</a>，写作规则见<a href="./../guides/documentation">维护项目文档</a>。</p><hr><p>源码版本：<code>a4354a6936c1</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/a4354a6936c10c0426b959ffa8f3debbc5afa68a/docs/getting-started/documentation.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>',12)])])}const p=t(o,[["render",n]]);export{f as __pageData,p as default};
